/**
 * Tab1 发起角色视图（agent-chain-ui-v2 §3，T-05 交付）。
 *
 * 把 P-01 v2.1 内联小弹窗两步流搬进侧滑 Tab1，宽屏化：
 *   - 第一步：选角色（launchable=true 卡片列表 + 子角色 chips）；
 *   - 第二步：填目标 textarea → buildAndSend → 自动调 panel-store.setOpen(false) 关侧滑。
 *
 * 数据流：
 *   - 角色列表：fetchRoles（workflow-api 既有；fetchImpl / inputActions 可注入）
 *   - 发起：buildAndSend（既有；成功 → 本组件调 panel-store.close 关闭侧滑）
 *
 * 错误处理：
 *   - fetchRoles 失败：内联显示（不抛，不弹窗）；
 *   - buildAndSend 失败：内联显示，按钮重新可用；
 *   - fetchRoles 进行中：渲染 loading 占位；空列表显示空态提示。
 *
 * 约束：
 *   - 纯 React 组件：不读 ctx，全部数据/回调走 props；
 *   - 样式内联（不引第三方 UI 库 / CSS Modules）；
 *   - 红线 8：组件文案与渲染内容不含 ASCII 双花括号占位符形态。
 *
 * 备注：WorkflowPanel.tsx 当前渲染 <LaunchView /> 时不传 props；fetchImpl / inputActions
 * 由 framework session kit 在 PropsRuntime<'conversation.input.right'> 上提供，本组件复用
 * 同款 PropsRuntime 即可在 Talkie 模式下被 dsh 注入 inputActions。
 */
import { useEffect, useState } from 'react'
import type { CSSProperties } from 'react'
import type { PropsRuntime } from '@deepseek-ai/dsh-client-ui-slots'
import { fetchRoles, buildAndSend, defaultFetch, type RoleSummaryDTO, type WorkflowFetch, type WorkflowInputActions } from '../workflow-api.ts'
import { setOpen, getActions, getSessionId } from './panel-store.ts'

/** 完整 props：runtime 份额（含 inputActions）+ InputZone owner 份额。 */
export type LaunchViewProps = PropsRuntime<'conversation.input.right'>

/**
 * Props 注入形态（测试用）：可选 fetchImpl / inputActions 覆盖默认行为。
 * - fetchImpl：fetchRoles / buildAndSend 调用时优先用 props.fetchImpl（沿 P-01 fetchRoles
 *   既有 fetchImpl = defaultFetch 注入形态）；
 * - inputActions：buildAndSend 写入草稿与提交的面（owner 提供；测试用 mock 替换）。
 * - onClose：成功后自定义关闭动作（默认 panel-store.setOpen(false)）。
 */
export interface LaunchViewInjectedProps {
  fetchImpl?: WorkflowFetch
  inputActions?: WorkflowInputActions
  onClose?: () => void
}

