// ---------------------------------------------------------------------------
// 工具：从 PropsRuntime 中解析 inputActions（容忍 props.inputActions 缺省）
// ---------------------------------------------------------------------------

/**
 * 从 PropsRuntime 中安全取得 inputActions。
 *
 * 解析顺序（R-06 T-05/1 修复）：
 *   1. props.inputActions 直接注入（测试 / preview 走 props）；
 *   2. props.useInput()().inputActions（session 域 standard kit 注入形态，
 *      仅 conversation.input.right 槽有效；本组件在 root 域 shell.overlay 不可用）；
 *   3. panel-store.getActions()（R-06 跨 slot 域桥接：session 域 RoleButton
 *      已把当前会话 inputActions 发布进 store，root 域 LaunchView 从 store 读）；
 *   4. 全部缺省 → null（显示「不支持直接发送」错误）。
 */
function getInputActions(props: LaunchViewProps & LaunchViewInjectedProps): WorkflowInputActions | null {
  if (props.inputActions !== undefined) return props.inputActions
  const runtime = (props as unknown as { useInput?: () => unknown }).useInput
  if (typeof runtime === 'function') {
    try {
      const v = runtime() as { inputActions?: WorkflowInputActions }
      if (v?.inputActions !== undefined) return v.inputActions
    } catch {
      // session kit 未注入，忽略
    }
  }
  // R-06 T-05/1：跨 slot 域桥接——root 域面板拿不到 session 域注入，从模块级 store 读
  const stored = getActions()
  if (stored !== null) return stored
  return null
}

// ---------------------------------------------------------------------------
// 主组件
// ---------------------------------------------------------------------------

/**
 * Tab1 发起角色视图：两步流（选角色 → 填目标 → 开始）。
 * 发起成功后自动调 panel-store.setOpen(false) 关闭侧滑。
 */
export function LaunchView(props: LaunchViewProps & LaunchViewInjectedProps): React.ReactElement {
  const fetchImpl = props.fetchImpl
  const onClose = props.onClose ?? (() => { setOpen(false) })

  // ---- 角色列表状态 ----
  const [roles, setRoles] = useState<RoleSummaryDTO[]>([])
  const [loading, setLoading] = useState<boolean>(true)
  const [loadError, setLoadError] = useState<string>('')

  // ---- 选中状态 ----
  const [selected, setSelected] = useState<RoleSummaryDTO | null>(null)
  const [goal, setGoal] = useState<string>('')
  const [busy, setBusy] = useState<boolean>(false)
  const [sendError, setSendError] = useState<string>('')

  // 拉取角色列表（仅一次，组件挂载时）
  useEffect(() => {
    let alive = true
    setLoading(true)
    setLoadError('')
    fetchRoles(fetchImpl)
      .then((list) => {
        if (!alive) return
        setRoles(list)
      })
      .catch((err: unknown) => {
        if (!alive) return
        setLoadError(err instanceof Error ? err.message : String(err))
      })
      .finally(() => {
        if (!alive) return
        setLoading(false)
      })
    return () => { alive = false }
    // fetchImpl 在 props 引用稳定时只跑一次；测试可换不同 fetchImpl 触发重拉。
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [fetchImpl])

  /** 选卡片 → 进入第二步 */
  function pickRole(role: RoleSummaryDTO): void {
    setSelected(role)
    setGoal('')
    setSendError('')
  }

  /** 取消 → 退回第一步 */
  function cancelPick(): void {
    setSelected(null)
    setGoal('')
    setSendError('')
  }

  /** 开始 → buildAndSend → 成功后自动关侧滑 */
  async function submitLaunch(): Promise<void> {
    if (selected === null || goal.trim() === '' || busy) return
    const actions = getInputActions(props)
    if (actions === null) {
      setSendError('当前上下文不支持直接发送（inputActions 未注入）')
      return
    }
    setBusy(true)
    setSendError('')
    try {
      // R08 问题 1：附带当前会话 id，node 半据此把角色协议注入该会话的 agent scope。
      await buildAndSend(fetchImpl ?? defaultFetch, actions, selected.id, goal.trim(), getSessionId())
      onClose()
    } catch (err) {
      setSendError(err instanceof Error ? err.message : String(err))
    } finally {
      setBusy(false)
    }
  }

  // ---- 渲染 ----

  if (selected !== null) {
    return (
      <div role="region" aria-label="第二步：填目标">
        <div style={STEP2_TITLE_STYLE}>
          以「{selected.name}」身份发起
        </div>
        <label style={GOAL_LABEL_STYLE} htmlFor="launch-view-goal">目标 *</label>
        <textarea
          id="launch-view-goal"
          value={goal}
          onChange={(event) => setGoal(event.target.value)}
          placeholder="例：完成登录模块开发并按规范评审"
          style={GOAL_TEXTAREA_STYLE}
          disabled={busy}
        />
        {sendError !== '' && (
          <div style={ERROR_STYLE} role="alert">{sendError}</div>
        )}
        <div style={FOOTER_STYLE}>
          <button
            type="button"
            onClick={cancelPick}
            style={BTN_SECONDARY_STYLE}
            disabled={busy}
          >
            取消
          </button>
          <button
            type="button"
            onClick={() => { void submitLaunch() }}
            style={goal.trim() === '' || busy ? BTN_DISABLED_STYLE : BTN_PRIMARY_STYLE}
            disabled={goal.trim() === '' || busy}
          >
            {busy ? '发起中…' : '▶ 开始'}
          </button>
        </div>
      </div>
    )
  }

  return (
    <div role="region" aria-label="第一步：选择角色">
      <div style={SECTION_TITLE_STYLE}>选择角色（launchable=true）</div>
      {loading && <div style={LOADING_STYLE}>角色加载中…</div>}
      {!loading && loadError !== '' && (
        <div style={ERROR_STYLE} role="alert">{loadError}</div>
      )}
      {!loading && loadError === '' && roles.length === 0 && (
        <div style={EMPTY_STYLE}>暂无可发起角色（请在 Tab2 新建）</div>
      )}
      {!loading && loadError === '' && roles.length > 0 && (
        <div style={CARD_LIST_STYLE}>
          {roles.map((role) => (
            <button
              key={role.id}
              type="button"
              onClick={() => pickRole(role)}
              style={ROLE_CARD_STYLE}
              aria-label={`选择角色 ${role.name}`}
            >
              <div style={ROLE_CARD_NAME_STYLE}>{role.name}</div>
              <div style={ROLE_CARD_SUMMARY_STYLE}>{role.summary}</div>
              {role.children.length > 0 && (
                <div style={CHIPS_ROW_STYLE}>
                  <span style={CHIP_STYLE}>子角色：</span>
                  {role.children.map((child) => (
                    <span key={child} style={CHIP_STYLE}>{child}</span>
                  ))}
                </div>
              )}
            </button>
          ))}
        </div>
      )}
    </div>
  )
}