/**
 * meow-dsh-workflow 浏览器半（browser half）入口 —— T-09 + T-02/T-03/T-05/T-07 交付。
 *
 * 双面插件包：node 半负责存储/AgentManager/meow_agent_call 工具/Web API
 * （/api/meow-workflow/*，T-08 + T-01）+ 管理页（/meow-workflow/agents，T-06）；
 * 本 browser 半向 dsh web SPA 注入 UI：
 *   1. `conversation.input.right` —— 输入框右端「角色」按钮（T-09 + T-03 改造：
 *      点击只打开侧滑，不再内联小弹窗，aria-pressed 反映开关态）；
 *   2. `shell.overlay`            —— 右侧工作流面板浮层（T-02，root 域加性浮层，
 *      双 Tab 头：Tab1 发起角色（T-05 LaunchView）/ Tab2 Agent 管理（T-07 AgentsView））。
 *
 * 两个槽独立，但共享模块级 `panel-store`（panel-store.ts）—— 输入框按钮在
 * session 域调用 `open()`，侧滑面板在 root 域用 `isOpen()` 同步状态，
 * 跨 slot 域天然。
 *
 * 构建：`tsdown.config.ts` 用 dsh 的 clientBundle 结构产出 `lib/client.js`
 * （浏览器 CJS + `window.__ModuleLoader__.load({ id: 'meow-dsh-workflow', factory })`）。
 *
 * 注意（类型面）：本文件对 `@deepseek-ai/*` 全部为 type-only import（含 SlotMap 合并），
 * 运行时零跨插件值导入 → 通过 client bundle 纯度门禁。
 */
import type { ClientContext } from '@deepseek-ai/dsh-client-runtime/client'
// Type-only：加载 ui-conversation / ui-layout 的 SlotMap 合并，
// 使 `conversation.input.right` / `shell.overlay` 成为已声明的 slot 键。
import type {} from '@deepseek-ai/dsh-client-ui-conversation/client'
import type {} from '@deepseek-ai/dsh-client-ui-layout/client'
import { RoleButton } from './RoleButton.tsx'
import { WorkflowPanel } from './WorkflowPanel.tsx'
import { LaunchView } from './LaunchView.tsx'
import { AgentsView } from './AgentsView.tsx'

export { RoleButton } from './RoleButton.tsx'
export type { RoleButtonProps } from './RoleButton.tsx'
export { WorkflowPanel } from './WorkflowPanel.tsx'
export type { WorkflowPanelProps } from './WorkflowPanel.tsx'
export { LaunchView } from './LaunchView.tsx'
export type { LaunchViewProps, LaunchViewInjectedProps } from './LaunchView.tsx'
export { AgentsView } from './AgentsView.tsx'
export type { AgentsViewProps } from './AgentsView.tsx'

/** 插件名（cordis 诊断标签；loader 条目名仍为包名 meow-dsh-workflow）。 */
export const name = 'meow-dsh-workflow-client'

/** 需要的服务：`slots`（SlotRegistry，由 @deepseek-ai/dsh-client-runtime 提供）。 */
export const inject = ['slots']

/**
 * 客户端插件体：注册输入框按钮 + 右侧工作流面板浮层（slot 注入，随插件卸载自动回收）。
 * @param ctx - 客户端根上下文（含 ctx.slots / ctx.effect 等 cordis 核心面）。
 */
export function apply(ctx: ClientContext): void {
  ctx.slots.inject('conversation.input.right', () => ctx.slots.register({
    name: 'conversation.input.right',
    id: 'meow-workflow',
    order: 20,
  }, RoleButton))

  ctx.slots.inject('shell.overlay', () => ctx.slots.register({
    name: 'shell.overlay',
    id: 'meow-workflow-panel',
  }, WorkflowPanel))
}