/**
 * meow-dsh-workflow 台账 tab —— 项目台账视图。
 *
 * 形态与 MemoryView/AgentsView 同构（iframe 容器）：src="/meow-workflow/ledger"，
 * node 半自包含单页（../static.ts 的 LEDGER_INDEX_HTML）提供——项目选择器 +
 * 各台账簿记录列表（只读），数据走 /api/meow-workflow/ledger。
 */
import type { CSSProperties } from 'react'

const IFRAME_STYLE: CSSProperties = {
  width: '100%',
  height: '100%',
  minHeight: '70vh',
  border: 0,
  display: 'block',
}

/** 台账视图 props 类型（保留扩展点；当前 WorkflowPanel 调用不传）。 */
export type LedgerViewProps = Record<string, never>

/** 台账视图：iframe 容器，嵌入 node 半自包含单页 /meow-workflow/ledger。 */
export function LedgerView(_props?: LedgerViewProps): React.ReactElement {
  return (
    <iframe
      src="/meow-workflow/ledger"
      title="Meow 工作流 · 项目台账"
      style={IFRAME_STYLE}
    />
  )
}
