/**
 * meow-dsh-workflow 浏览器半 —— 工作流面板（侧滑）开关的共享状态（模块级 store）。
 *
 * 输入框按钮（conversation.input.right，session 域）与右侧浮层
 * （shell.overlay，root 域）挂在**不同的 slot 作用域**上，但需要共享同一个
 * 「面板打开/关闭」状态以及「当前会话 inputActions 快照」。这里用模块级发布订阅
 * + React `useSyncExternalStore` 桥接（不依赖 cordis store，跨 slot 域天然共享；
 * 插件卸载即随 bundle 释放）。
 *
 * 与 meow-dsh-task panel-store 同款（形态对齐以便评审对照）：
 *   - `subscribe(fn) → unsubscribe`：发布订阅契约（React useSyncExternalStore 兼容）；
 *   - `getOpen()`：当前状态快照（布尔值，引用稳定，可直接作为 useSyncExternalStore 的 getSnapshot）；
 *   - `setOpen(next)`：设置开关；无变化时 no-op（避免无谓重渲染）；
 *   - `toggleOpen()`：切换开关。
 *
 * R-06 T-05/1 修复：root 域面板拿不到 inputActions（session 域 standard kit 只把
 * useInput/inputActions 注入 conversation.input.right，不注入 shell.overlay）。
 * 因此 session 域 RoleButton 把当前会话 inputActions 发布进模块级 store，
 * root 域 LaunchView 从 store 读取——跨 slot 域桥接。
 *   - `getActions()`：当前会话 inputActions 快照（可能为 null，未发布时）；
 *   - `setActions(actions)`：发布/清除 actions 快照；引用变化时通知监听者。
 *
 * 这是浏览器半的内部实现细节，不参与任何跨插件值导入（无 @deepseek-ai 运行时依赖）。
 */

import type { WorkflowInputActions } from '../workflow-api.ts'

type Listener = () => void

let open = false
let actions: WorkflowInputActions | null = null
const listeners = new Set<Listener>()
const actionsListeners = new Set<Listener>()

/** 订阅开关变化；返回退订函数（React useSyncExternalStore 契约）。 */
export function subscribe(fn: Listener): () => void {
  listeners.add(fn)
  return () => {
    listeners.delete(fn)
  }
}

/** 当前开关状态快照（布尔值，引用稳定，可直接作为 useSyncExternalStore 的 getSnapshot）。 */
export function getOpen(): boolean {
  return open
}

/** 打开/关闭面板；无变化时 no-op（避免无谓重渲染）。 */
export function setOpen(next: boolean): void {
  if (open === next) return
  open = next
  for (const fn of [...listeners]) fn()
}

/** 切换面板开关。 */
export function toggleOpen(): void {
  setOpen(!open)
}

// ---------------------------------------------------------------------------
// R-06 T-05/1：跨 slot 域 inputActions 桥接
// ---------------------------------------------------------------------------

/**
 * 订阅 inputActions 变化；返回退订函数。
 * RoleButton（session 域）发布 / LaunchView（root 域）订阅，跨 slot 域共享。
 */
export function subscribeActions(fn: Listener): () => void {
  actionsListeners.add(fn)
  return () => {
    actionsListeners.delete(fn)
  }
}

/**
 * 当前 inputActions 快照（可能为 null：未发布 / 已清除）。
 * 引用稳定（同一 actions 对象不变化），可直接作为 useSyncExternalStore 的 getSnapshot。
 */
export function getActions(): WorkflowInputActions | null {
  return actions
}

/**
 * 发布/清除 inputActions。
 * - `next === null`：清除快照（组件卸载或会话切换时调用）；
 * - `next !== null`：发布新快照；引用变化时通知 actions 监听者。
 * - 同一引用 no-op（避免无谓重渲染）。
 */
export function setActions(next: WorkflowInputActions | null): void {
  if (actions === next) return
  actions = next
  for (const fn of [...actionsListeners]) fn()
}

// ---------------------------------------------------------------------------
// R08 问题 1：跨 slot 域 sessionId 桥接
// ---------------------------------------------------------------------------

/**
 * 跨 slot 域共享「当前会话 id」：session 域 RoleButton 从 PropsRuntime 拿到
 * sessionId 发布进模块级 store，root 域 LaunchView（buildAndSend）从 store 读取并
 * 随 build-prompt 请求传给 node 端，node 端据此把角色协议注入该会话的 agent scope。
 * 与 inputActions 桥接（R-06 T-05/1）同款形态；会话切换/组件卸载时清除。
 */

let sessionId: string | null = null
const sessionIdListeners = new Set<Listener>()

/** 订阅 sessionId 变化；返回退订函数（React useSyncExternalStore 契约）。 */
export function subscribeSessionId(fn: Listener): () => void {
  sessionIdListeners.add(fn)
  return () => {
    sessionIdListeners.delete(fn)
  }
}

/** 当前会话 id 快照（可能为 null：未发布 / 已清除）。 */
export function getSessionId(): string | null {
  return sessionId
}

/**
 * 发布/清除当前会话 id。
 * - `next === null`：清除快照（组件卸载或会话切换时调用）；
 * - `next !== null`：发布新快照；变化时通知监听者。
 * - 同一引用 no-op（避免无谓重渲染）。
 */
export function setSessionId(next: string | null): void {
  if (sessionId === next) return
  sessionId = next
  for (const fn of [...sessionIdListeners]) fn()
}
