/**
 * 右侧工作流面板浮层（shell.overlay 槽，T-02 + T-05 交付）。
 *
 * ui-layout 的 `shell.overlay` 是加性全屏浮层（root 域，列表槽），
 * 它的渲染层 `.overlayLayer` 默认 click-through（pointer-events: none），
 * 条目根节点由 CSS 恢复 pointer-events: auto（`.overlayLayer > *`）。
 *
 * 与 meow-dsh-task 的 TaskPanel 完全同构（docs/agent-chain-ui-v2 §2 + §9）：
 *   - 全屏遮罩 `rgba(15,23,42,0.35)`；
 *   - 右停靠 80% 宽 / max-width 1100px 面板；
 *   - header：标题「Meow 工作流」+ Tab 切换 + 关闭 ×；
 *   - 面板内部点击 `stopPropagation` 不冒泡（避免误关）；
 *   - 关闭时渲染 null（完全卸载，不占布局）。
 *
 * 四 Tab 头：
 *   - 发起角色：渲染 <LaunchView />（T-05 交付 — 选角色→填目标→开始，
 *     复用 workflow-api 的 fetchRoles/buildAndSend，成功后自动关闭侧滑）；
 *   - Agent 管理：渲染 <AgentsView />（T-07 交付 — iframe 容器，
 *     src=/meow-workflow/agents，node 半自包含单页）；
 *   - 记忆：渲染 <MemoryView />（iframe 容器，src=/meow-workflow/memory，
 *     项目选择器 + 各角色记忆列表，只读）；
 *   - 台账：渲染 <LedgerView />（iframe 容器，src=/meow-workflow/ledger，
 *     项目选择器 + 各台账簿记录列表，只读）。
 *
 * 面板开关走模块级 panel-store（panel-store.ts），与 RoleButton（conversation.input.right
 * 槽，session 域）共享状态——跨 slot 域天然。
 */
import { useState, useSyncExternalStore } from 'react'
import type { CSSProperties } from 'react'
import type { PropsRuntime } from '@deepseek-ai/dsh-client-ui-slots'
import { getOpen, setOpen, subscribe } from './panel-store.ts'
import { LaunchView } from './LaunchView.tsx'
import { AgentsView } from './AgentsView.tsx'
import { MemoryView } from './MemoryView.tsx'
import { LedgerView } from './LedgerView.tsx'

/** 完整 props：runtime 份额（root 域，无 owner 份额）。 */
export type WorkflowPanelProps = PropsRuntime<'shell.overlay'>

/** Tab 标识：发起角色 / Agent 管理 / 记忆 / 台账。 */
type WorkflowTab = 'launch' | 'agents' | 'memory' | 'ledger'

const OVERLAY_STYLE: CSSProperties = {
  position: 'absolute',
  inset: 0,
  zIndex: 30,
  background: 'rgba(15, 23, 42, 0.35)',
}

const PANEL_STYLE: CSSProperties = {
  position: 'absolute',
  top: 0,
  right: 0,
  bottom: 0,
  width: '80%',
  maxWidth: '1100px',
  display: 'flex',
  flexDirection: 'column',
  background: 'var(--dsw-alias-bg-base, #fff)',
  borderLeft: '1px solid var(--dsw-alias-border-l2, #e2e5ea)',
  boxShadow: '-8px 0 24px rgba(0, 0, 0, 0.18)',
}

const HEADER_STYLE: CSSProperties = {
  flex: 'none',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'space-between',
  gap: 8,
  height: 44,
  padding: '0 12px 0 16px',
  borderBottom: '1px solid var(--dsw-alias-border-l1, #eceff3)',
  fontSize: 14,
  fontWeight: 600,
  color: 'var(--dsw-alias-label-primary, #111827)',
}

const TAB_GROUP_STYLE: CSSProperties = {
  display: 'inline-flex',
  gap: 4,
}

const TAB_BTN_ACTIVE: CSSProperties = {
  height: 28,
  padding: '0 12px',
  border: '1px solid var(--dsw-alias-border-l2, #e2e5ea)',
  borderRadius: 6,
  background: 'var(--dsw-alias-accent, #2563eb)',
  color: '#fff',
  fontSize: 13,
  cursor: 'pointer',
}

const TAB_BTN_INACTIVE: CSSProperties = {
  height: 28,
  padding: '0 12px',
  border: '1px solid var(--dsw-alias-border-l2, #e2e5ea)',
  borderRadius: 6,
  background: 'var(--dsw-alias-bg-base, #fff)',
  color: 'var(--dsw-alias-label-primary, #111827)',
  fontSize: 13,
  cursor: 'pointer',
}

const CLOSE_BTN_STYLE: CSSProperties = {
  width: 28,
  height: 28,
  border: 'none',
  borderRadius: 6,
  background: 'transparent',
  color: 'var(--dsw-alias-label-tertiary, #6b7280)',
  fontSize: 18,
  lineHeight: 1,
  cursor: 'pointer',
}

const TAB_BODY_STYLE: CSSProperties = {
  flex: 1,
  minHeight: 0,
  overflow: 'auto',
  padding: '16px',
}

/**
 * 右侧工作流面板浮层：面板关闭时渲染 null（完全卸载，不占布局）。
 * 三 Tab：发起角色 / Agent 管理 / 记忆。
 */
export function WorkflowPanel(_props: WorkflowPanelProps): React.ReactElement | null {
  const isOpen = useSyncExternalStore(subscribe, getOpen)
  const [activeTab, setActiveTab] = useState<WorkflowTab>('launch')
  if (!isOpen) return null
  return (
    <div style={OVERLAY_STYLE} onClick={() => setOpen(false)}>
      <div style={PANEL_STYLE} onClick={(event) => event.stopPropagation()}>
        <div style={HEADER_STYLE}>
          <span>Meow 工作流</span>
          <div style={TAB_GROUP_STYLE} role="tablist" aria-label="工作流面板 Tab 切换">
            <button
              type="button"
              role="tab"
              aria-selected={activeTab === 'launch'}
              aria-label="发起角色"
              title="发起角色"
              onClick={() => setActiveTab('launch')}
              style={activeTab === 'launch' ? TAB_BTN_ACTIVE : TAB_BTN_INACTIVE}
            >
              发起角色
            </button>
            <button
              type="button"
              role="tab"
              aria-selected={activeTab === 'agents'}
              aria-label="Agent 管理"
              title="Agent 管理"
              onClick={() => setActiveTab('agents')}
              style={activeTab === 'agents' ? TAB_BTN_ACTIVE : TAB_BTN_INACTIVE}
            >
              Agent 管理
            </button>
            <button
              type="button"
              role="tab"
              aria-selected={activeTab === 'memory'}
              aria-label="记忆"
              title="记忆"
              onClick={() => setActiveTab('memory')}
              style={activeTab === 'memory' ? TAB_BTN_ACTIVE : TAB_BTN_INACTIVE}
            >
              记忆
            </button>
            <button
              type="button"
              role="tab"
              aria-selected={activeTab === 'ledger'}
              aria-label="台账"
              title="台账"
              onClick={() => setActiveTab('ledger')}
              style={activeTab === 'ledger' ? TAB_BTN_ACTIVE : TAB_BTN_INACTIVE}
            >
              台账
            </button>
          </div>
          <button
            type="button"
            aria-label="关闭工作流面板"
            title="关闭"
            onClick={() => setOpen(false)}
            style={CLOSE_BTN_STYLE}
          >
            ×
          </button>
        </div>
        <div style={TAB_BODY_STYLE}>
          {activeTab === 'launch' ? (
            <LaunchView />
          ) : activeTab === 'agents' ? (
            <AgentsView />
          ) : activeTab === 'ledger' ? (
            <LedgerView />
          ) : (
            <MemoryView />
          )}
        </div>
      </div>
    </div>
  )
}
