/**
 * meow-dsh-workflow Tab2 —— Agent 管理视图（T-07）。
 *
 * 形态（与 meow-dsh-task TaskPanel iframe 容器同构，docs/agent-chain-ui-v2.md §9 一致性）：
 *   - 简单 iframe 容器：src="/meow-workflow/agents"（相对路径，dsh web 同源加载）；
 *   - node 半自包含单页（../static.ts 的 AGENTS_INDEX_HTML）经 exact /meow-workflow/agents
 *     路由提供，数据经同源 /api/meow-workflow/{agents,tools} fetch，
 *     browser 半零本地文件读取；
 *   - 无 fetch / 无状态管理需求（直接 iframe 加载 node 半自包含单页）；
 *   - iframe 自带 scroll（无需外层 overflow:auto）。
 *
 * 注：本组件当前不读取 `useSessions` 工作区——meow-dsh-workflow 的 agents.json 单一
 * 数据根（$DSH_HOME/meow-dsh-workflow/），无 per-workspace 拆分；如未来要拆分可
 * 在此处复用 TaskPanel 的 useSessions 模式注入 ?workspace=。
 */
import type { CSSProperties } from 'react'

const IFRAME_STYLE: CSSProperties = {
  width: '100%',
  height: '100%',
  minHeight: '70vh',
  border: 0,
  display: 'block',
}

/** Tab2 Agent 管理视图 props 类型（保留扩展点；当前 WorkflowPanel 调用不传）。 */
export type AgentsViewProps = Record<string, never>

/** Tab2 Agent 管理视图：iframe 容器，嵌入 node 半自包含单页 /meow-workflow/agents。 */
export function AgentsView(_props?: AgentsViewProps): React.ReactElement {
  return (
    <iframe
      src="/meow-workflow/agents"
      title="Meow 工作流 · Agent 管理"
      style={IFRAME_STYLE}
    />
  )
}

/** 静态资源：iframe 样式常量（测试可见）。 */
export const AGENTS_IFRAME_STYLE: CSSProperties = IFRAME_STYLE
