/**
 * 输入框右端「角色」按钮（conversation.input.right 槽，T-09 + T-03 改造）。
 *
 * v2.1 形态（T-09）：按钮 → 内联小弹窗两步流（拉角色 / 目标 / 开始）。
 * v2 形态（T-03 改造）：按钮 → 只切换工作流面板开关（panel-store.toggleOpen），
 * aria-pressed 反映开关态。具体两步流在 WorkflowPanel 的 Tab1（LaunchView，
 * T-05 交付）中渲染——本按钮仅作为入口。
 *
 * R-06 T-05/1 修复：本按钮（session 域）持有 framework standard kit 注入的
 * inputActions；root 域 LaunchView 拿不到这些 props。本组件在挂载/更新时把
 * 解析到的 inputActions 发布进模块级 panel-store（setActions），让 LaunchView
 * 从 store 读取——跨 slot 域桥接。会话切换或组件卸载时清除（setActions(null)）。
 *
 * 数据流：所有角色列表 / 提示词组装 / 发送均发生在 Tab1（LaunchView）内，
 * 走 standard kit 的 inputActions（setDraft + submit），由 T-05 接盘实现。
 * 本组件**不再**直接 import workflow-api，也不持 useState/useEffect 用于面板开关——
 * 开关状态由模块级 panel-store 托管（跨 slot 域：session 域按钮 + root 域面板共享）。
 *
 * 约束：
 *   - 纯 React 组件：不读 ctx，全部数据/回调走 props（framework session kit 提供
 *     useInput/inputActions；owner 提供 InputZone）；
 *   - 样式内联（不引第三方 UI 库 / CSS Modules）；
 *   - 红线 8：按钮文案与渲染内容不含 ASCII 双花括号占位符形态。
 */
import { useEffect, useSyncExternalStore } from 'react'
import type { PropsRuntime } from '@deepseek-ai/dsh-client-ui-slots'
import type { WorkflowInputActions } from '../workflow-api.ts'
import { getOpen, subscribe, toggleOpen, setActions, setSessionId } from './panel-store.ts'

/** 完整 props：framework runtime 份额（含 useInput/inputActions）+ InputZone owner 份额。 */
export type RoleButtonProps = PropsRuntime<'conversation.input.right'>

const BUTTON_STYLE: React.CSSProperties = {
  display: 'inline-flex',
  alignItems: 'center',
  gap: 4,
  height: 24,
  padding: '0 8px',
  border: '1px solid var(--dsw-alias-border-l2, #e2e5ea)',
  borderRadius: 6,
  background: 'var(--dsw-alias-bg-base, #fff)',
  color: 'var(--dsw-alias-label-primary, #111827)',
  fontSize: 12,
  lineHeight: 1,
  cursor: 'pointer',
  whiteSpace: 'nowrap',
}

/**
 * 从 PropsRuntime 中安全解析 inputActions（容忍 props.inputActions 缺省 + useInput 注入形态）。
 * 沿 LaunchView.getInputActions 形态：直接 props.inputActions → useInput()().inputActions → null。
 */
function resolveInputActions(props: RoleButtonProps): WorkflowInputActions | null {
  const direct = (props as unknown as { inputActions?: WorkflowInputActions }).inputActions
  if (direct !== undefined) return direct
  const useInput = (props as unknown as { useInput?: () => unknown }).useInput
  if (typeof useInput === 'function') {
    try {
      const v = useInput() as { inputActions?: WorkflowInputActions }
      if (v?.inputActions !== undefined) return v.inputActions
    } catch {
      // session kit 未注入，忽略
    }
  }
  return null
}

/**
 * 从 PropsRuntime 中安全解析当前会话 id（R08 问题 1）。
 * 会话域 slot（conversation.input.right）的 framework standard kit 会注入
 * sessionId prop（ui-session 合并声明）；此处鸭子类型取值，容忍缺省。
 */
function resolveSessionId(props: RoleButtonProps): string | null {
  const v = (props as unknown as { sessionId?: string }).sessionId
  return typeof v === 'string' && v.trim() !== '' ? v.trim() : null
}

/**
 * 角色按钮：点击只切换工作流面板（侧滑）开关。aria-pressed 反映当前开关态。
 * 两步流（选角色 → 填目标 → 发起）由 WorkflowPanel Tab1（LaunchView，T-05 交付）承载。
 * 顺带把当前会话 inputActions 发布进 panel-store（R-06 T-05/1 跨 slot 域桥接）。
 */
export function RoleButton(props: RoleButtonProps): React.ReactElement {
  const isOpen = useSyncExternalStore(subscribe, getOpen)
  // R-06 T-05/1 + R08 问题 1：解析 props 的 inputActions / sessionId 并发布进 store；
  // 组件卸载时清除（避免下一个会话继承旧 actions / sessionId —— 会话切换时 framework
  // 按 session identity 重挂载本组件，cleanup 会先清、新挂载再发布）。
  useEffect(() => {
    const actions = resolveInputActions(props)
    setActions(actions)
    setSessionId(resolveSessionId(props))
    return () => {
      setActions(null)
      setSessionId(null)
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [props])
  return (
    <button
      type="button"
      title="选择角色发起"
      aria-label="选择角色发起"
      aria-pressed={isOpen}
      onClick={toggleOpen}
      style={BUTTON_STYLE}
    >
      <span aria-hidden="true">👤</span>
      <span>角色</span>
    </button>
  )
}
