/**
 * meow-dsh-workflow 记忆 tab —— 项目记忆视图。
 *
 * 形态与 AgentsView 同构（iframe 容器）：src="/meow-workflow/memory"，
 * node 半自包含单页（../static.ts 的 MEMORY_INDEX_HTML）提供——项目选择器 +
 * 各角色记忆列表（只读），数据走 /api/meow-workflow/memory。
 */
import type { CSSProperties } from 'react'

const IFRAME_STYLE: CSSProperties = {
  width: '100%',
  height: '100%',
  minHeight: '70vh',
  border: 0,
  display: 'block',
}

/** 记忆视图 props 类型（保留扩展点；当前 WorkflowPanel 调用不传）。 */
export type MemoryViewProps = Record<string, never>

/** 记忆视图：iframe 容器，嵌入 node 半自包含单页 /meow-workflow/memory。 */
export function MemoryView(_props?: MemoryViewProps): React.ReactElement {
  return (
    <iframe
      src="/meow-workflow/memory"
      title="Meow 工作流 · 项目记忆"
      style={IFRAME_STYLE}
    />
  )
}
